    "sequenceInfo",
    "sourceUrl",
    "minTotalCredits",
    "yearList"
  ],
  "additionalProperties": false,
  "definitions": {
    "semester": {
      "type": "object",
      "properties": {
        "courseList": {
          "type": "array",
          "items": {
            "oneOf": [
              {
                "$ref": "#/definitions/regularCourse"
              },
              {
                "$ref": "#/definitions/electiveCourse"
              },
              {
                "$ref": "#/definitions/orList"
              }
            ]
          }
        },
        "isWorkTerm": {
          "type": "string",
          "enum": [
            "true",
            "false"
          ]
        }
      },
      "required": [
        "courseList",
        "isWorkTerm"
      ],
      "additionalProperties": false
    },
