      "description": "A list of courses where the student can choose any one of them to add to take in the current semester",
      "type": "array",
      "items": {
        "oneOf": [
          {
            "$ref": "#/definitions/regularCourse"
          },
          {
            "$ref": "#/definitions/electiveCourse"
          }
        ]
      },
      "minItems": 2
    },
    "regularCourse": {
      "type": "object",
      "properties": {
        "code": {
          "type": "string",
          "pattern": "^\\w{4}\\s{1}\\d{3}$"
        },
        "isElective": {
          "type": "string",
          "pattern": "^false$"
        },
        "electiveType": {
          "type": "string",
          "pattern": "^$"
        }
      },
      "required": [
        "code",
        "isElective",
        "electiveType"
      ],
      "additionalProperties": false
    },
    "electiveCourse": {
      "type": "object",
      "properties": {
        "code": {
          "type": "string",
          "pattern": "^$"
        },
        "isElective": {
          "type": "string",
          "pattern": "^true$"
        },
        "electiveType": {
          "type": "string",
          "enum": [
            "Science",
            "Program",
            "General"
          ]
        }
      },
      "required": [
        "code",
        "isElective",
        "electiveType"
      ],
      "additionalProperties": false
    }
  }
}

